function totalStock(stock) {
  let sum = 0;
  for (const key of Object.keys(stock)) {
    sum += key;
  }
  return sum;
}

solution:
function totalStock(stock) {
  let sum = 0;
  for (const key of Object.keys(stock)) {
    sum += stock[key];
  }
  return sum;
}

